        System.out.println("Divisor: " + divisor);

        BigDecimal parcela = total.multiply(taxaMensal).divide(divisor, 10, RoundingMode.HALF_EVEN);
        System.out.println("Parcela: " + parcela);

        parcela = parcela.setScale(2, RoundingMode.HALF_EVEN);
        System.out.println("Parcela arredondada: " + parcela);

        BigDecimal totalComJuros = parcela.multiply(new BigDecimal(parcelas));
        System.out.println("Total com juros: " + totalComJuros);

        BigDecimal juros = totalComJuros.subtract(total);
        System.out.println("Juros: " + juros);
    }
}
